  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,0}'::int[], array[$j$The word gospel means good news.$j$,$j$Luke was a physician and wrote with careful detail.$j$,$j$Matthew 1:21 says He shall save His people from their sins.$j$,$j$Jesus was born in Bethlehem, the city of David (Luke 2:4 to 7).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Four Gospels and the Birth of Jesus$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: The Baptism, Temptation and Teaching of Jesus$j$, $j${"questions": [{"q": "Who baptized Jesus in the Jordan River?", "options": ["John the Baptist", "Peter", "Paul", "Andrew"]}, {"q": "What did the voice from heaven say at the baptism of Jesus?", "options": ["This is my beloved Son, in whom I am well pleased", "Follow me", "Peace be unto you", "Repent, for the kingdom is at hand"]}, {"q": "How did Jesus answer each temptation from Satan?", "options": ["He stayed silent", "He called on angels at once", "He quoted Scripture and said it is written", "He walked away without speaking"]}, {"q": "What is the name of Jesus' famous teaching that begins with the Beatitudes?", "options": ["The Upper Room Prayer", "The Parable of the Sower", "The Sermon on the Mount", "The Olivet Discourse"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Baptism, Temptation and Teaching of Jesus$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,2}'::int[], array[$j$John the Baptist baptized Jesus (Matthew 3:13 to 17).$j$,$j$Matthew 3:17 records the Father's words.$j$,$j$Jesus answered with the written Word of God (Matthew 4:4, 7 and 10).$j$,$j$Matthew 5 to 7 is called the Sermon on the Mount.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Baptism, Temptation and Teaching of Jesus$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: The Miracles and Parables of Jesus$j$, $j${"questions": [{"q": "What did Jesus say to the wind and the sea in Mark 4:39?", "options": ["Rise and walk", "Be thou clean", "Peace, be still", "Follow me"]}, {"q": "What is a parable?", "options": ["A prayer for the sick", "A list of laws", "A short story from everyday life that teaches a spiritual truth", "A song of praise"]}, {"q": "Who did Jesus raise from the dead after four days in the tomb?", "options": ["Jairus' daughter", "Stephen", "Lazarus", "The widow's son"]}, {"q": "What did the father do when he saw his son returning in the parable of the prodigal son?", "options": ["He demanded repayment", "He sent him away", "He waited inside the house", "He had compassion, ran and embraced him"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Miracles and Parables of Jesus$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,3}'::int[], array[$j$Jesus said, Peace, be still, and there was a great calm.$j$,$j$A parable uses an ordinary story to show a spiritual truth.$j$,$j$John 11 tells how Jesus raised Lazarus.$j$,$j$Luke 15:20 says the father had compassion, and ran, and fell on his neck.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Miracles and Parables of Jesus$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: The Cross and the Resurrection$j$, $j${"questions": [{"q": "What did Jesus pray on the cross in Luke 23:34?", "options": ["Send twelve legions of angels", "Let this cup pass from me", "Father, forgive them; for they know not what they do", "Remember me in your kingdom"]}, {"q": "According to John 3:16, why did God give His only begotten Son?", "options": ["Because He loved the world", "Because Israel had earned it", "Because the law required a king", "Because the temple was destroyed"]}, {"q": "What did the angel say at the empty tomb in Matthew 28:6?", "options": ["Go and sin no more", "Fear not, for I bring good tidings", "He is not here: for he is risen, as he said", "The kingdom is at hand"]}, {"q": "What does the Great Commission ask believers to do?", "options": ["Guard the tomb", "Rebuild the temple", "Go and teach all nations", "Keep the Passover"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Cross and the Resurrection$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,2}'::int[], array[$j$Jesus asked the Father to forgive those who crucified Him.$j$,$j$God so loved the world that He gave His Son.$j$,$j$The angel announced the resurrection of Jesus.$j$,$j$Matthew 28:19 says to go and teach all nations.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Cross and the Resurrection$j$ on conflict (item_id) do nothing;
